
   CREATE SEQUENCE  "APP"."TICKET_SEQ"	MINVALUE 100 MAXVALUE 999999 INCREMENT BY 5 START WITH 100 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  GLOBAL ;


  CREATE TABLE "APP"."CUSTOMERS"
   (	"ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"EMAIL" VARCHAR2(255) NOT NULL ENABLE,
	"FULL_NAME" CLOB,
	"IS_ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,
	"SCORE" NUMBER(10,2) DEFAULT 0,
	"STATUS" VARCHAR2(20) DEFAULT 'draft' NOT NULL ENABLE,
	"REFERRED_BY" NUMBER,
	"CREATED_AT" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
	 CONSTRAINT "CHK_CUSTOMERS_SCORE" CHECK (score >= 0) ENABLE,
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE,
	 CONSTRAINT "UQ_CUSTOMERS_EMAIL" UNIQUE ("EMAIL")
  USING INDEX  ENABLE,
	 CONSTRAINT "FK_CUSTOMERS_REFERRER" FOREIGN KEY ("REFERRED_BY")
	  REFERENCES "APP"."CUSTOMERS" ("ID") ON DELETE SET NULL ENABLE
   ) ;


  CREATE TABLE "APP"."ORDERS"
   (	"ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"CUSTOMER_ID" NUMBER NOT NULL ENABLE,
	"TOTAL" NUMBER(12,2) NOT NULL ENABLE,
	"PLACED_ON" DATE NOT NULL ENABLE,
	"NOTE" VARCHAR2(200) DEFAULT 'none',
	"TOTAL_WITH_TAX" NUMBER(12,2) GENERATED ALWAYS AS (total * 1.20) VIRTUAL,
	 CONSTRAINT "CHK_ORDERS_TOTAL" CHECK (total >= 0) ENABLE,
	 CONSTRAINT "PK_ORDERS" PRIMARY KEY ("ID")
  USING INDEX  ENABLE,
	 CONSTRAINT "UQ_ORDERS_DAY" UNIQUE ("CUSTOMER_ID", "PLACED_ON")
  USING INDEX  ENABLE,
	 CONSTRAINT "FK_ORDERS_CUSTOMER" FOREIGN KEY ("CUSTOMER_ID")
	  REFERENCES "APP"."CUSTOMERS" ("ID") ON DELETE CASCADE ENABLE
   ) ;


  CREATE TABLE "APP"."ORDER_LINES"
   (	"ORDER_ID" NUMBER NOT NULL ENABLE,
	"LINE_NO" NUMBER NOT NULL ENABLE,
	"SKU" VARCHAR2(64) NOT NULL ENABLE,
	"QTY" NUMBER DEFAULT 1 NOT NULL ENABLE,
	 CONSTRAINT "PK_ORDER_LINES" PRIMARY KEY ("ORDER_ID", "LINE_NO")
  USING INDEX  ENABLE,
	 CONSTRAINT "FK_LINES_ORDER" FOREIGN KEY ("ORDER_ID")
	  REFERENCES "APP"."ORDERS" ("ID") ON DELETE CASCADE ENABLE
   ) ;


  CREATE OR REPLACE FORCE EDITIONABLE VIEW "APP"."ACTIVE_CUSTOMERS" ("ID", "EMAIL", "SCORE") AS
  SELECT id, email, score FROM customers WHERE is_active = 1;


  CREATE OR REPLACE EDITIONABLE PROCEDURE "APP"."ARCHIVE_ORDERS" (cutoff IN DATE) IS
BEGIN
  DELETE FROM orders WHERE placed_on < cutoff;
END;
/


  CREATE OR REPLACE EDITIONABLE TRIGGER "APP"."CUSTOMERS_TOUCH" BEFORE INSERT ON customers FOR EACH ROW
BEGIN
  :NEW.created_at := SYSTIMESTAMP;
END;
/
ALTER TRIGGER "APP"."CUSTOMERS_TOUCH" ENABLE;


  CREATE OR REPLACE EDITIONABLE FUNCTION "APP"."ORDER_TOTAL" (p_order_id IN NUMBER) RETURN NUMBER IS
  t NUMBER;
BEGIN
  SELECT NVL(SUM(qty), 0) INTO t FROM order_lines WHERE order_id = p_order_id;
  RETURN t;
END;
/


  CREATE UNIQUE INDEX "APP"."IDX_CUSTOMERS_STATUS_EMAIL" ON "APP"."CUSTOMERS" ("STATUS", "EMAIL")
  ;


  CREATE INDEX "APP"."IDX_LINES_SKU_QTY" ON "APP"."ORDER_LINES" ("SKU", "QTY")
  ;


  CREATE INDEX "APP"."IDX_ORDERS_CUSTOMER" ON "APP"."ORDERS" ("CUSTOMER_ID")
  ;


COMMENT ON TABLE "CUSTOMERS" IS 'people who buy things';
COMMENT ON COLUMN "CUSTOMERS"."EMAIL" IS 'login address, unique';

  CREATE OR REPLACE TYPE "APP"."ADDR_T" AS OBJECT ("STREET" VARCHAR2(100), "CITY" VARCHAR2(60))
/

  GRANT SELECT ON "APP"."CUSTOMERS" TO "REPORTING"
/
  GRANT SELECT, INSERT ON "APP"."ORDERS" TO "REPORTING"
/
